// Shellharden reimplementation
// Main entry point and CLI handling

use std::env;
use std::fs;
use std::io::{self, Read, Write};
use std::path::PathBuf;
use std::process::ExitCode;

mod syntax;
mod output;

use output::OutputMode;

const VERSION: &str = "4.3.1";

const HELP_TEXT: &str = "\
Shellharden: The corrective bash syntax highlighter.

Usage:
\tshellharden [options] [files]
\tcat files | shellharden [options] ''

Shellharden is a syntax highlighter and a tool to semi-automate the rewriting
of scripts to ShellCheck conformance, mainly focused on quoting.

The default mode of operation is like `cat`, but with syntax highlighting in
foreground colors and suggestive changes in background colors.

Options:
\t--suggest         Output a colored diff suggesting changes.
\t--syntax          Output syntax highlighting with ANSI colors.
\t--syntax-suggest  Diff with syntax highlighting (default mode).
\t--transform       Output suggested changes.
\t--check           No output; exit with 2 if changes are suggested.
\t--replace         Replace file contents with suggested changes.
\t--                Don't treat further arguments as options.
\t-h|--help         Show help text.
\t--version         Show version.

The changes suggested by Shellharden inhibits word splitting and indirect
pathname expansion. This will make your script ShellCheck compliant in terms of
quoting. Whether your script will work afterwards is a different question:
If your script was using those features on purpose, it obviously won't anymore!

Every script is possible to write without using word splitting or indirect
pathname expansion, but it may involve doing things differently.
See the accompanying file how_to_do_things_safely_in_bash.md or online:
https://github.com/anordal/shellharden/blob/master/how_to_do_things_safely_in_bash.md
";

fn main() -> ExitCode {
    let args: Vec<String> = env::args().collect();
    let mut mode = OutputMode::SyntaxSuggest;
    let mut files: Vec<PathBuf> = Vec::new();
    let mut parse_opts = true;
    let mut iter = args.iter().skip(1);
    while let Some(a) = iter.next() {
        if parse_opts && a.starts_with('-') && a != "-" {
            match a.as_str() {
                "--" => { parse_opts = false; }
                "-h" | "--help" => {
                    print!("{}", HELP_TEXT);
                    return ExitCode::from(0);
                }
                "--version" => {
                    println!("{}", VERSION);
                    return ExitCode::from(0);
                }
                "--suggest" => { mode = OutputMode::Suggest; }
                "--syntax" => { mode = OutputMode::Syntax; }
                "--syntax-suggest" => { mode = OutputMode::SyntaxSuggest; }
                "--transform" => { mode = OutputMode::Transform; }
                "--check" => { mode = OutputMode::Check; }
                "--replace" => { mode = OutputMode::Replace; }
                other => {
                    eprintln!("{}: No such option.", other);
                    return ExitCode::from(3);
                }
            }
        } else {
            files.push(PathBuf::from(a));
        }
    }

    let mut any_error = false;
    let mut any_change = false;

    if files.is_empty() {
        return ExitCode::from(0);
    }

    for f in &files {
        match process_one(f, mode) {
            Ok(changed) => {
                if changed { any_change = true; }
            }
            Err(e) => {
                eprintln!("{}: {}", f.display(), e);
                any_error = true;
            }
        }
    }

    if any_error {
        return ExitCode::from(1);
    }
    if mode == OutputMode::Check && any_change {
        return ExitCode::from(2);
    }
    ExitCode::from(0)
}

fn process_one(path: &PathBuf, mode: OutputMode) -> Result<bool, String> {
    let data: Vec<u8>;
    let is_stdin = path.as_os_str().is_empty();
    if is_stdin {
        let mut buf = Vec::new();
        io::stdin().read_to_end(&mut buf).map_err(|e| format!("{}", e))?;
        data = buf;
    } else {
        data = fs::read(path).map_err(|e| format!("{} (os error {})",
            e.to_string().split(" (").next().unwrap_or(&e.to_string()).to_string(),
            e.raw_os_error().unwrap_or(0)))?;
    }

    let input = String::from_utf8_lossy(&data).to_string();

    let mut out = Vec::<u8>::new();
    let result = syntax::process(&input, mode, &mut out);

    match mode {
        OutputMode::Check => {
            // silent
        }
        OutputMode::Replace => {
            if is_stdin {
                io::stdout().write_all(&out).ok();
            } else if result.changed {
                fs::write(path, &out).map_err(|e| format!("{}", e))?;
            }
        }
        _ => {
            io::stdout().write_all(&out).ok();
        }
    }

    if let Some(err_msg) = result.error {
        // Print syntactic-pitfall or end-of-file error messages to stderr
        eprintln!("{}", err_msg);
        return Err("Unsupported syntax".to_string());
    }
    Ok(result.changed)
}
