// Output mode and color definitions

#[derive(Copy, Clone, PartialEq, Eq, Debug)]
pub enum OutputMode {
    Suggest,
    Syntax,
    SyntaxSuggest,
    Transform,
    Check,
    Replace,
}

impl OutputMode {
    // Does this mode emit syntax (foreground) colors?
    pub fn syntax(self) -> bool {
        matches!(self, OutputMode::Syntax | OutputMode::SyntaxSuggest)
    }
    // Does this mode highlight suggested changes (background)?
    pub fn suggest(self) -> bool {
        matches!(self, OutputMode::Suggest | OutputMode::SyntaxSuggest)
    }
    // Does this mode apply the transformation?
    pub fn transform(self) -> bool {
        matches!(self, OutputMode::Transform | OutputMode::Check | OutputMode::Replace)
    }
    // Is any output produced in stdout?
    pub fn produces_output(self) -> bool {
        !matches!(self, OutputMode::Check)
    }
}

// ANSI escapes
pub const RESET: &str = "\x1b[m";

// Foreground colors (24-bit RGB)
pub const COL_KEYWORD: &str = "\x1b[0;1m";  // bold
pub const COL_COMMAND: &str = "\x1b[0;38;2;192;0;128m";  // magenta-ish
pub const COL_DQUOTE: &str = "\x1b[0;38;2;255;0;0m"; // red
pub const COL_SQUOTE: &str = "\x1b[0;38;2;255;204;85m"; // yellow
pub const COL_VAR: &str = "\x1b[0;38;2;63;127;207m"; // blue
pub const COL_ASSIGN: &str = "\x1b[0;38;2;0;127;255m"; // lighter blue
pub const COL_COMMENT: &str = "\x1b[0;1;3;38;2;120;144;96m"; // olive italic
pub const COL_ESCAPE: &str = "\x1b[0;1;38;2;255;0;128m"; // bold magenta
pub const COL_HEREDOC: &str = "\x1b[0;38;2;128;32;0m"; // brown
pub const COL_DBRACKET: &str = "\x1b[0;38;2;192;0;192m"; // [[ ... ]]

// Background colors for suggestion
pub const BG_INSERT: &str = "\x1b[0;42m";  // green background
pub const BG_DELETE: &str = "\x1b[0;41m";  // red background
RUST_EOF
