                }
                let text = &self.src[start..self.pos].to_vec();
                self.emit_fg(Some(COL_VAR));
                self.put_bytes(text);
                self.emit_fg(None);
            }
            _ => {
                // Just a lone $
                self.emit_fg(None);
                self.raw(b'$');
            }
        }
        Ok(())
    }

