// Core bash tokenizer + transformer/highlighter.
// Implements enough of bash syntax to match common cases.

use crate::output::{OutputMode, *};

pub struct ProcessResult {
    pub changed: bool,
    pub error: Option<String>,
}

pub fn process(input: &str, mode: OutputMode, out: &mut Vec<u8>) -> ProcessResult {
    let mut p = Parser::new(input, mode);
    match p.run() {
        Ok(()) => {
            if mode.produces_output() {
                out.extend_from_slice(&p.output);
            }
            ProcessResult { changed: p.changed, error: None }
        }
        Err(e) => {
            if mode.produces_output() {
                out.extend_from_slice(&p.output);
            }
            ProcessResult { changed: p.changed, error: Some(e) }
        }
    }
}

// Contexts that influence whether to suggest quotes.
#[derive(Copy, Clone, PartialEq, Eq, Debug)]
enum Ctx {
    // Top-level / normal command word position
    Normal,
    // Inside a double-quoted string
    DQuoted,
    // Right-hand side of assignment (safe - no quoting needed)
    Assignment,
    // Inside [[ ... ]]
    DoubleBracket,
    // Inside case pattern (case $var in)
    CaseHead,
    // Inside arithmetic $((...)) or ((...))
    Arith,
    // Inside an array assignment like a=(...)
    ArrayAssign,
    // Inside single-quoted - nothing happens
    SQuoted,
    // Inside heredoc body with quotes (no expansion)
    HeredocQuoted,
    // Heredoc body without quotes
    Heredoc,
}

impl Ctx {
    fn needs_quoting(self) -> bool {
        matches!(self, Ctx::Normal | Ctx::ArrayAssign)
    }
}

// Tracks the current foreground/background "state" so we can coalesce escapes.
struct Parser<'a> {
    src: &'a [u8],
    pos: usize,
    mode: OutputMode,
    output: Vec<u8>,
    changed: bool,
    // stack of pending closing tokens, for nesting tracking.
    // (unused for now, but could be useful)
    cur_fg: Option<&'static str>, // current foreground color set
    cur_bg: Option<&'static str>, // current background color set (insert/delete)
}

// Keywords that are highlighted as shell keywords (bold, no color).
fn is_keyword(w: &str) -> bool {
    matches!(w,
        "if" | "then" | "elif" | "else" | "fi" |
        "for" | "in" | "do" | "done" |
        "while" | "until" | "select" |
        "case" | "esac" |
        "function" |
        "{" | "}" |
        "export" | "local" | "declare" | "readonly" |
        "time" | "!"
    )
}

fn is_id_start(b: u8) -> bool {
    b == b'_' || (b >= b'a' && b <= b'z') || (b >= b'A' && b <= b'Z')
}
fn is_id_cont(b: u8) -> bool {
    is_id_start(b) || (b >= b'0' && b <= b'9')
}
fn is_word_char(b: u8) -> bool {
    match b {
        b' ' | b'\t' | b'\n' | b'\r' | b';' | b'&' | b'|' | b'(' | b')' |
        b'<' | b'>' | b'\'' | b'"' | b'`' | b'\\' | b'#' | b'=' => false,
        _ => true,
    }
}

impl<'a> Parser<'a> {
    fn new(src: &'a str, mode: OutputMode) -> Self {
        Parser {
            src: src.as_bytes(),
            pos: 0,
            mode,
            output: Vec::new(),
            changed: false,
            cur_fg: None,
            cur_bg: None,
        }
    }

    // ---- output helpers ----
    fn emit_fg(&mut self, color: Option<&'static str>) {
        if !self.mode.syntax() { return; }
        if self.cur_fg == color && self.cur_bg.is_none() {
            return;
        }
        // Reset first
        if self.cur_bg.is_some() || self.cur_fg.is_some() {
            self.output.extend_from_slice(RESET.as_bytes());
            self.cur_bg = None;
        }
        if let Some(c) = color {
            self.output.extend_from_slice(c.as_bytes());
        }
        self.cur_fg = color;
    }

    // Strong reset (end of a color)
    fn reset_all(&mut self) {
        if self.mode.syntax() || self.mode.suggest() {
            if self.cur_fg.is_some() || self.cur_bg.is_some() {
                self.output.extend_from_slice(RESET.as_bytes());
                self.cur_fg = None;
                self.cur_bg = None;
            }
        }
    }

    fn emit_bg(&mut self, bg: Option<&'static str>) {
        if !self.mode.suggest() { return; }
        if self.cur_bg == bg { return; }
        self.reset_all();
        if let Some(b) = bg {
            self.output.extend_from_slice(b.as_bytes());
        }
        self.cur_bg = bg;
        self.cur_fg = None;
    }

    // Emit plain bytes with current color.
    fn put_bytes(&mut self, b: &[u8]) {
        self.output.extend_from_slice(b);
    }
    fn put_str(&mut self, s: &str) {
        self.output.extend_from_slice(s.as_bytes());
    }

    // Emit text with a specific foreground color set (and reset at end only if requested).
    fn emit_colored(&mut self, color: &'static str, text: &[u8]) {
        if self.mode.syntax() {
            self.emit_fg(Some(color));
        }
        self.output.extend_from_slice(text);
    }

    // Plain raw output (no color change, suitable for spaces/punctuation between colored tokens).
    fn raw(&mut self, b: u8) {
        self.output.push(b);
    }

    // ---- parser ----
    fn run(&mut self) -> Result<(), String> {
        self.parse_block(Ctx::Normal, None)?;
        self.reset_all();
        Ok(())
    }

    // Parse until end-of-input or until one of the given "end" bytes.
    // Returns without consuming the end byte.
    fn parse_block(&mut self, ctx: Ctx, end: Option<u8>) -> Result<(), String> {
        let mut start_of_cmd = true;
        loop {
            if self.pos >= self.src.len() {
                if let Some(_e) = end {
                    return Err(format!("Unexpected end of file\nThe file's end was reached without closing all sytactic scopes.\nEither, the parser got lost, or the file is truncated or malformed."));
                }
                return Ok(());
            }
            let b = self.src[self.pos];
            if let Some(e) = end {
                if b == e {
                    return Ok(());
                }
                // Handle matching for `)` and ``
                if e == b')' && b == b'`' {
                    // don't match
                }
            }
            match b {
                b' ' | b'\t' => {
                    self.emit_fg(None);
                    self.raw(b);
                    self.pos += 1;
                }
                b'\n' | b'\r' => {
                    self.emit_fg(None);
                    self.raw(b);
                    self.pos += 1;
                    start_of_cmd = true;
                }
                b';' | b'&' | b'|' => {
                    self.emit_fg(None);
                    self.raw(b);
                    self.pos += 1;
                    // Check if followed by another to handle ;; && || |
                    if self.pos < self.src.len() && (self.src[self.pos] == b || (b==b'|' && self.src[self.pos]==b'|')) {
                        self.raw(self.src[self.pos]);
                        self.pos += 1;
                    }
                    start_of_cmd = true;
                }
                b'(' => {
                    // Subshell
                    self.emit_fg(None);
                    self.raw(b);
                    self.pos += 1;
                    self.parse_block(Ctx::Normal, Some(b')'))?;
                    if self.pos < self.src.len() && self.src[self.pos] == b')' {
                        self.emit_fg(None);
                        self.raw(b')');
                        self.pos += 1;
                    } else {
                        return Err(format!("Unexpected end of file\nThe file's end was reached without closing all sytactic scopes.\nEither, the parser got lost, or the file is truncated or malformed."));
                    }
                    start_of_cmd = false;
                }
                b'#' => {
                    // Comment to end of line
                    let start = self.pos;
                    while self.pos < self.src.len() && self.src[self.pos] != b'\n' {
                        self.pos += 1;
                    }
                    let text = &self.src[start..self.pos];
                    self.emit_fg(Some(COL_COMMENT));
                    self.put_bytes(text);
                    self.emit_fg(None);
                }
                _ => {
                    // Try to parse a command (or other construct) starting here
                    self.parse_command(ctx, start_of_cmd, end)?;
                    start_of_cmd = false;
                }
            }
        }
    }

    fn parse_command(&mut self, outer_ctx: Ctx, is_start: bool, end: Option<u8>) -> Result<(), String> {
        // Read the first word; determine what it is
        // It could be: a keyword, an assignment, a command, or start of a compound command
        let saved_pos = self.pos;
        let w = self.read_word_simple();
        // If it's a keyword, handle specially
        match w.as_str() {
            "" => {
                // Can't happen unless special char; fall back to raw read
                if self.pos < self.src.len() {
                    let b = self.src[self.pos];
                    self.raw(b);
                    self.pos += 1;
                }
                return Ok(());
            }
            kw if is_keyword(kw) && is_start => {
                self.emit_fg(Some(COL_KEYWORD));
                self.put_str(kw);
                self.emit_fg(None);
                // Special handling for some keywords that introduce loops.
                match kw {
                    "for" | "select" => {
                        // read var name
                        self.skip_spaces_keep();
                        let v = self.read_word_simple();
                        if !v.is_empty() {
                            self.emit_fg(Some(COL_KEYWORD));
                            // emit space prefix color nothing
                            // actually we need to emit as "for "<VAR>" "in ...
                            // reset since space was already emitted
                        }
                        // parse the var name and "in" keyword ourselves
                        // Restore: the space was skipped by skip_spaces_keep already emitting
                        // so we need a different approach
                        // NOTE: skip_spaces_keep inside here already emitted the space.
                        // Now emit var name as COL_ASSIGN (with surrounding keyword style)
                        if !v.is_empty() {
                            self.emit_fg(Some(COL_ASSIGN));
                            self.put_str(&v);
                        }
                        // Continue parsing the rest normally
                    }
                    _ => {}
                }
                return Ok(());
            }
            _ => {}
        }

        // Not a keyword - handle as assignment or command
        // Check if the word has '=' with identifier prefix
        if let Some((name, rest)) = split_assignment(&w) {
            // It's an assignment
            // Emit name as assignment color, then '=' then rest
            self.pos = saved_pos;
            // Emit var name
            self.emit_fg(Some(COL_ASSIGN));
            self.put_str(name);
            self.pos += name.len();
            self.emit_fg(None);
            // Emit '='
            self.raw(b'=');
            self.pos += 1;
            // Now parse the rest as an assignment RHS (parts may be quoted, etc.)
            let _ = rest;
            self.parse_word_contents(Ctx::Assignment)?;
            return Ok(());
        }

        // Otherwise, it's a command name.
        self.pos = saved_pos;
        // Emit command name
        self.emit_fg(Some(COL_COMMAND));
        self.put_str(&w);
        self.pos += w.len();
        self.emit_fg(None);

        // Now parse the rest of the command line: arguments
        self.parse_arg_list(outer_ctx, end)?;
        Ok(())
    }

    fn parse_arg_list(&mut self, _outer: Ctx, end: Option<u8>) -> Result<(), String> {
        loop {
            if self.pos >= self.src.len() { return Ok(()); }
            let b = self.src[self.pos];
            if let Some(e) = end {
                if b == e { return Ok(()); }
            }
            match b {
                b'\n' | b';' | b'&' | b'|' => return Ok(()),
                b' ' | b'\t' | b'\r' => {
                    self.emit_fg(None);
                    self.raw(b);
                    self.pos += 1;
                }
                _ => {
                    self.parse_word_contents(Ctx::Normal)?;
                }
            }
        }
    }

    // Parse contents of a word (possibly containing quotes, variables, etc.)
    fn parse_word_contents(&mut self, ctx: Ctx) -> Result<(), String> {
        let mut first = true;
        while self.pos < self.src.len() {
            let b = self.src[self.pos];
            // word ends at whitespace/metachars (unless inside quotes etc.)
            match b {
                b' ' | b'\t' | b'\n' | b'\r' | b';' | b'|' | b'&' | b')' => return Ok(()),
                _ => {}
            }
            match b {
                b'"' => {
                    self.parse_double_quoted()?;
                }
                b'\'' => {
                    self.parse_single_quoted()?;
                }
                b'$' => {
                    self.parse_dollar(ctx)?;
                }
                b'`' => {
                    self.parse_backtick(ctx)?;
                }
                b'\\' => {
                    // Escape sequence
                    self.emit_fg(Some(COL_ESCAPE));
                    self.raw(b'\\');
                    self.pos += 1;
                    if self.pos < self.src.len() {
                        self.raw(self.src[self.pos]);
                        self.pos += 1;
                    }
                    self.emit_fg(None);
                }
                _ => {
                    self.emit_fg(None);
                    self.raw(b);
                    self.pos += 1;
                }
            }
            first = false;
            let _ = first;
        }
        Ok(())
    }

    fn parse_double_quoted(&mut self) -> Result<(), String> {
        // Read a double-quoted string. Emit red color.
        // Variables inside are highlighted in blue.
        self.emit_fg(Some(COL_DQUOTE));
        self.raw(b'"');
        self.pos += 1;
        while self.pos < self.src.len() {
            let b = self.src[self.pos];
            match b {
                b'"' => {
                    self.emit_fg(Some(COL_DQUOTE));
                    self.raw(b'"');
                    self.pos += 1;
                    self.emit_fg(None);
                    return Ok(());
                }
                b'\\' => {
                    self.emit_fg(Some(COL_DQUOTE));
                    self.raw(b'\\');
                    self.pos += 1;
                    if self.pos < self.src.len() {
                        self.raw(self.src[self.pos]);
                        self.pos += 1;
                    }
                }
                b'$' => {
                    self.parse_dollar(Ctx::DQuoted)?;
                    self.emit_fg(Some(COL_DQUOTE));
                }
                b'`' => {
                    self.parse_backtick(Ctx::DQuoted)?;
                    self.emit_fg(Some(COL_DQUOTE));
                }
                _ => {
                    self.emit_fg(Some(COL_DQUOTE));
                    self.raw(b);
                    self.pos += 1;
                }
            }
        }
        Err(format!("Unexpected end of file\nThe file's end was reached without closing all sytactic scopes.\nEither, the parser got lost, or the file is truncated or malformed."))
    }

    fn parse_single_quoted(&mut self) -> Result<(), String> {
        self.emit_fg(Some(COL_SQUOTE));
        self.raw(b'\'');
        self.pos += 1;
        while self.pos < self.src.len() {
            let b = self.src[self.pos];
            if b == b'\'' {
                self.raw(b'\'');
                self.pos += 1;
                self.emit_fg(None);
                return Ok(());
            }
            self.raw(b);
            self.pos += 1;
        }
        Err(format!("Unexpected end of file\nThe file's end was reached without closing all sytactic scopes.\nEither, the parser got lost, or the file is truncated or malformed."))
    }

    fn parse_dollar(&mut self, ctx: Ctx) -> Result<(), String> {
        // Already at '$'
        // Check what follows
        if self.pos + 1 >= self.src.len() {
            self.emit_fg(None);
            self.raw(b'$');
            self.pos += 1;
            return Ok(());
        }
        let nxt = self.src[self.pos + 1];
        match nxt {
            b'(' => {
                // $( or $((
                if self.pos + 2 < self.src.len() && self.src[self.pos + 2] == b'(' {
                    // $((...))
                    self.emit_fg(Some(COL_DBRACKET));
                    // read until )) matching
                    let start = self.pos;
                    self.pos += 3;
                    let mut depth = 2i32;
                    while self.pos < self.src.len() && depth > 0 {
                        let b = self.src[self.pos];
                        if b == b'(' { depth += 1; }
                        else if b == b')' { depth -= 1; }
                        self.pos += 1;
                    }
                    self.put_bytes(&self.src[start..self.pos].to_vec());
                    self.emit_fg(None);
                } else {
                    // $(...)
                    // Emit: $( then parse inner as commands, then )
                    self.emit_fg(None);
                    self.put_str("$(");
                    self.pos += 2;
                    self.parse_block(Ctx::Normal, Some(b')'))?;
                    if self.pos < self.src.len() && self.src[self.pos] == b')' {
                        self.emit_fg(None);
                        self.raw(b')');
                        self.pos += 1;
                    }
                }
            }
            b'{' => {
                // ${...}
                self.parse_brace_var(ctx)?;
            }
            _ => {
                // simple variable
                self.parse_simple_var(ctx)?;
            }
        }
        Ok(())
    }

    fn parse_brace_var(&mut self, _ctx: Ctx) -> Result<(), String> {
        // Parse ${...}
        let start = self.pos;
        self.pos += 2; // skip ${
        let mut depth = 1i32;
        while self.pos < self.src.len() && depth > 0 {
            match self.src[self.pos] {
                b'{' => depth += 1,
                b'}' => depth -= 1,
                _ => {}
            }
            if depth > 0 { self.pos += 1; }
        }
        // Include the closing }
        if self.pos < self.src.len() { self.pos += 1; }
        let text = &self.src[start..self.pos].to_vec();
        self.emit_fg(Some(COL_VAR));
        self.put_bytes(text);
        self.emit_fg(None);
        Ok(())
    }

    fn parse_simple_var(&mut self, _ctx: Ctx) -> Result<(), String> {
        // Parse $name or $special
        let start = self.pos;
        self.pos += 1; // skip $
        if self.pos >= self.src.len() {
            // just $ alone
            self.emit_fg(None);
            self.put_bytes(b"$");
            return Ok(());
        }
        let b = self.src[self.pos];
        match b {
            b'?' | b'$' | b'!' | b'#' | b'@' | b'*' | b'-' | b'_' => {
                self.pos += 1;
                let text = &self.src[start..self.pos].to_vec();
                self.emit_fg(Some(COL_VAR));
                self.put_bytes(text);
                self.emit_fg(None);
            }
            b'0'..=b'9' => {
                self.pos += 1;
                let text = &self.src[start..self.pos].to_vec();
                self.emit_fg(Some(COL_VAR));
                self.put_bytes(text);
                self.emit_fg(None);
            }
            c if is_id_start(c) => {
                while self.pos < self.src.len() && is_id_cont(self.src[self.pos]) {
                    self.pos += 1;
                }
                let text = &self.src[start..self.pos].to_vec();
                self.emit_fg(Some(COL_VAR));
                self.put_bytes(text);
                self.emit_fg(None);
            }
            _ => {
                // Just a lone $
                self.emit_fg(None);
                self.raw(b'$');
            }
        }
        Ok(())
    }

    fn parse_backtick(&mut self, _ctx: Ctx) -> Result<(), String> {
        // Preserve backticks as-is with highlighting inside (simplified)
        self.emit_fg(None);
        self.raw(b'`');
        self.pos += 1;
        while self.pos < self.src.len() && self.src[self.pos] != b'`' {
            self.parse_word_contents_in_backtick()?;
        }
        if self.pos < self.src.len() && self.src[self.pos] == b'`' {
            self.emit_fg(None);
            self.raw(b'`');
            self.pos += 1;
        }
        Ok(())
    }

    fn parse_word_contents_in_backtick(&mut self) -> Result<(), String> {
        // Minimal: parse command inside, but stop at backtick
        while self.pos < self.src.len() && self.src[self.pos] != b'`' {
            let b = self.src[self.pos];
            if b == b'\\' {
                self.pos += 1;
                if self.pos < self.src.len() { self.raw(b'\\'); self.raw(self.src[self.pos]); self.pos += 1; }
                continue;
            }
            // For now, treat inside like a normal block but stop at `
            // We'll read a word and emit it as command first, rest as-is
            break;
        }
        if self.pos >= self.src.len() || self.src[self.pos] == b'`' { return Ok(()); }
        // Parse like a block until `
        self.parse_block(Ctx::Normal, Some(b'`'))
    }

    // Read a contiguous word (simple, non-quoted, non-dollar) to identify a token.
    fn read_word_simple(&self) -> String {
        let mut i = self.pos;
        let mut s = String::new();
        while i < self.src.len() {
            let b = self.src[i];
            if !is_word_char(b) { break; }
            s.push(b as char);
            i += 1;
        }
        s
    }

    fn skip_spaces_keep(&mut self) {
        while self.pos < self.src.len() {
            let b = self.src[self.pos];
            if b == b' ' || b == b'\t' {
                self.raw(b);
                self.pos += 1;
            } else {
                break;
            }
        }
    }
}

fn split_assignment(w: &str) -> Option<(&str, &str)> {
    // Returns (name, rest) if w starts with IDENT=
    let bytes = w.as_bytes();
    if bytes.is_empty() { return None; }
    if !is_id_start(bytes[0]) { return None; }
    let mut i = 1;
    while i < bytes.len() && is_id_cont(bytes[i]) { i += 1; }
    if i < bytes.len() && bytes[i] == b'=' {
        return Some((&w[..i], &w[i+1..]));
    }
    None
}
