// Output mode and color definitions

#[derive(Copy, Clone, PartialEq, Eq, Debug)]
pub enum OutputMode {
    Suggest,
    Syntax,
    SyntaxSuggest,
    Transform,
    Check,
    Replace,
}

impl OutputMode {
    pub fn syntax(self) -> bool {
        matches!(self, OutputMode::Syntax | OutputMode::SyntaxSuggest)
    }
    pub fn suggest(self) -> bool {
        matches!(self, OutputMode::Suggest | OutputMode::SyntaxSuggest)
    }
    pub fn transform(self) -> bool {
        matches!(self, OutputMode::Transform | OutputMode::Check | OutputMode::Replace)
    }
    pub fn produces_output(self) -> bool {
        !matches!(self, OutputMode::Check)
    }
}

pub const RESET: &str = "\x1b[m";
pub const COL_KEYWORD: &str = "\x1b[0;1m";
pub const COL_COMMAND: &str = "\x1b[0;38;2;192;0;128m";
pub const COL_DQUOTE: &str = "\x1b[0;38;2;255;0;0m";
pub const COL_SQUOTE: &str = "\x1b[0;38;2;255;204;85m";
pub const COL_VAR: &str = "\x1b[0;38;2;63;127;207m";
pub const COL_ASSIGN: &str = "\x1b[0;38;2;0;127;255m";
pub const COL_COMMENT: &str = "\x1b[0;1;3;38;2;120;144;96m";
pub const COL_ESCAPE: &str = "\x1b[0;1;38;2;255;0;128m";
pub const COL_HEREDOC: &str = "\x1b[0;38;2;128;32;0m";
pub const COL_DBRACKET: &str = "\x1b[0;38;2;192;0;192m";

pub const BG_INSERT: &str = "\x1b[0;42m";
pub const BG_DELETE: &str = "\x1b[0;41m";

// A Sink is the output buffer with helpers that respect OutputMode.
pub struct Sink {
    pub mode: OutputMode,
    pub out: Vec<u8>,
    pub changed: bool,
    cur_fg: &'static str, // "" means no color active
    cur_bg: &'static str, // "" means no bg active
}

impl Sink {
    pub fn new(mode: OutputMode) -> Self {
        Sink {
            mode,
            out: Vec::new(),
            changed: false,
            cur_fg: "",
            cur_bg: "",
        }
    }

    // Raw bytes with current fg color (no change notation)
    pub fn raw(&mut self, b: &[u8]) {
        if !self.mode.produces_output() { return; }
        self.out.extend_from_slice(b);
    }

    pub fn raw_s(&mut self, s: &str) {
        self.raw(s.as_bytes());
    }

    // Set foreground color (if syntax mode). Bg stays.
    pub fn fg(&mut self, color: &'static str) {
        if !self.mode.syntax() { return; }
        if !self.mode.produces_output() { return; }
        if self.cur_fg == color && self.cur_bg == "" {
            return;
        }
        // Need to emit: reset + optional bg + fg
        // In the original, each new fg reset + apply color.
        self.out.extend_from_slice(RESET.as_bytes());
        self.cur_bg = "";
        if !color.is_empty() {
            self.out.extend_from_slice(color.as_bytes());
        }
        self.cur_fg = color;
    }

    // Full reset of colors.
    pub fn end_color(&mut self) {
        if !self.mode.produces_output() { return; }
        if !self.mode.syntax() && !self.mode.suggest() { return; }
        if !self.cur_fg.is_empty() || !self.cur_bg.is_empty() {
            self.out.extend_from_slice(RESET.as_bytes());
            self.cur_fg = "";
            self.cur_bg = "";
        }
    }

    pub fn bg(&mut self, bg: &'static str) {
        if !self.mode.produces_output() { return; }
        if !self.mode.suggest() { return; }
        if self.cur_bg == bg { return; }
        // Reset and apply bg
        self.out.extend_from_slice(RESET.as_bytes());
        self.cur_fg = "";
        if !bg.is_empty() {
            self.out.extend_from_slice(bg.as_bytes());
        }
        self.cur_bg = bg;
    }

    // End-of-line handling: clear any active color at a newline
    pub fn newline_reset(&mut self) {
        self.end_color();
    }
}
