// Bash parser / highlighter / transformer.
// Focused on matching the observed behavior of shellharden 4.3.1 on common inputs.

use crate::output::*;

pub struct ProcessResult {
    pub changed: bool,
    pub error: Option<String>,
}

pub fn process(input: &str, mode: OutputMode, out: &mut Vec<u8>) -> ProcessResult {
    let mut p = Parser::new(input.as_bytes(), mode);
    let err = match p.parse_script(EndCond::Eof) {
        Ok(()) => None,
        Err(e) => Some(e),
    };
    p.sink.end_color();
    out.extend_from_slice(&p.sink.out);
    ProcessResult { changed: p.sink.changed, error: err }
}

#[derive(Copy, Clone, PartialEq, Eq)]
enum EndCond {
    Eof,
    RParen,     // stop at )
    Backtick,   // stop at `
    DoneKw,     // stop at `done` (loop body) - unused (we treat sequentially)
    Brace,      // stop at `}`
}

// Whether $var needs quoting in this context
#[derive(Copy, Clone, PartialEq, Eq)]
enum QuoteCtx {
    Needed,       // outside quotes, command word/argument
    Safe,         // inside [[ ]], case head, assignment RHS, already in dquote
    InDQuote,     // we're already inside a double-quoted string
    InHeredoc,    // inside heredoc (no expansion rewrites)
}

struct Parser<'a> {
    src: &'a [u8],
    pos: usize,
    sink: Sink,
}

// ---------- Identifier helpers ----------
fn is_id_start(b: u8) -> bool {
    b == b'_' || (b >= b'a' && b <= b'z') || (b >= b'A' && b <= b'Z')
}
fn is_id_cont(b: u8) -> bool {
    is_id_start(b) || (b >= b'0' && b <= b'9')
}
fn is_metachar(b: u8) -> bool {
    matches!(b, b' ' | b'\t' | b'\n' | b'\r' | b'|' | b'&' | b';' | b'(' | b')' | b'<' | b'>')
}

// True if this word is a shell keyword (when appearing in command position).
fn is_keyword(w: &str) -> bool {
    matches!(w,
        "if" | "then" | "elif" | "else" | "fi" |
        "for" | "do" | "done" |
        "while" | "until" | "select" | "in" |
        "case" | "esac" |
        "function" |
        "{" | "}" |
        "export" | "local" | "declare" | "readonly"
    )
}

fn err_eof() -> String {
    "Unexpected end of file\nThe file's end was reached without closing all sytactic scopes.\nEither, the parser got lost, or the file is truncated or malformed.".to_string()
}

fn err_pitfall_10() -> String {
    "Unsupported syntax: Syntactic pitfall\n$10\n^^^\nThis does not mean what it looks like. You may be forgiven to think that the full string of numerals is the variable name. Only the fist is.\n\nTry this and be shocked: f() { echo \"$9\" \"$10\"; }; f a b c d e f g h i j\n\nHere is where braces should be used to disambiguate, e.g. \"${10}\" vs \"${1}0\".\n\nSyntactic pitfalls are deemed too dangerous to fix automatically\n(the purpose of Shellharden is to fix vulnerable code – code that mostly does what it looks like, as opposed to code that never does what it looks like):\n* Fixing what it does would be 100% subtle and might slip through code review unnoticed.\n* Fixing its look would make a likely bug look intentional.".to_string()
}

impl<'a> Parser<'a> {
    fn new(src: &'a [u8], mode: OutputMode) -> Self {
        Parser { src, pos: 0, sink: Sink::new(mode) }
    }

    fn peek(&self, offset: usize) -> Option<u8> {
        self.src.get(self.pos + offset).copied()
    }

    fn eof(&self) -> bool { self.pos >= self.src.len() }

    // Copy current byte (with current color).
    fn emit1(&mut self) {
        if !self.eof() {
            let b = [self.src[self.pos]];
            self.sink.raw(&b);
            self.pos += 1;
        }
    }

    // ---------- Script parsing ----------
    fn parse_script(&mut self, end: EndCond) -> Result<(), String> {
        // Top-level: read commands until end condition or EOF.
        loop {
            self.skip_blanks_and_newlines();
            if self.check_end(end) { return Ok(()); }
            if self.eof() {
                match end {
                    EndCond::Eof => return Ok(()),
                    _ => return Err(err_eof()),
                }
            }
            self.parse_command_chain(end)?;
        }
    }

    fn check_end(&self, end: EndCond) -> bool {
        if self.eof() { return end == EndCond::Eof; }
        match end {
            EndCond::Eof => false,
            EndCond::RParen => self.src[self.pos] == b')',
            EndCond::Backtick => self.src[self.pos] == b'`',
            EndCond::Brace => self.src[self.pos] == b'}',
            EndCond::DoneKw => false, // handled via keyword parsing
        }
    }

    // Skip horizontal whitespace and newlines and comments, emitting them.
    fn skip_blanks_and_newlines(&mut self) {
        while !self.eof() {
            let b = self.src[self.pos];
            match b {
                b' ' | b'\t' | b'\n' | b'\r' => {
                    self.sink.fg("");
                    self.emit1();
                }
                b'#' => {
                    self.emit_comment();
                }
                _ => break,
            }
        }
    }

    fn emit_comment(&mut self) {
        let start = self.pos;
        while self.pos < self.src.len() && self.src[self.pos] != b'\n' {
            self.pos += 1;
        }
        self.sink.fg(COL_COMMENT);
        self.sink.raw(&self.src[start..self.pos].to_vec());
        self.sink.fg("");
    }

    fn parse_command_chain(&mut self, end: EndCond) -> Result<(), String> {
        // Parse one command, then check for operators (| || && ; &)
        self.parse_one_command(end)?;
        loop {
            // horizontal whitespace only (no newlines)
            self.skip_horiz();
            if self.eof() { return Ok(()); }
            if self.check_end(end) { return Ok(()); }
            let b = self.src[self.pos];
            match b {
                b'\n' => return Ok(()),
                b'#' => { self.emit_comment(); return Ok(()); }
                b';' | b'&' | b'|' => {
                    self.sink.fg("");
                    self.emit1();
                    if !self.eof() {
                        let b2 = self.src[self.pos];
                        if (b == b';' && b2 == b';') || (b == b'&' && b2 == b'&') || (b == b'|' && b2 == b'|') {
                            self.emit1();
                        }
                    }
                    self.skip_blanks_and_newlines();
                    if self.eof() || self.check_end(end) { return Ok(()); }
                    self.parse_one_command(end)?;
                }
                _ => return Ok(()),
            }
        }
    }

    fn skip_horiz(&mut self) {
        while !self.eof() {
            let b = self.src[self.pos];
            if b == b' ' || b == b'\t' {
                self.sink.fg("");
                self.emit1();
            } else { break; }
        }
    }

    // Parse a single "simple command" or compound construct.
    fn parse_one_command(&mut self, _end: EndCond) -> Result<(), String> {
        // Read potential leading redirections / assignments / name
        // First, see if we have a keyword/compound at the start
        if self.eof() { return Ok(()); }
        let b = self.src[self.pos];
        match b {
            b'(' => {
                // subshell
                self.sink.fg("");
                self.emit1();
                self.parse_script(EndCond::RParen)?;
                if self.peek(0) == Some(b')') {
                    self.sink.fg("");
                    self.emit1();
                } else {
                    return Err(err_eof());
                }
                return Ok(());
            }
            b'{' => {
                // Is this a brace group? Only if followed by whitespace
                // We check word boundaries
                let w = self.read_bare_word();
                if w == "{" {
                    self.sink.fg(COL_KEYWORD);
                    self.sink.raw_s("{");
                    self.sink.fg("");
                    self.pos += 1;
                    self.parse_script(EndCond::Brace)?;
                    if self.peek(0) == Some(b'}') {
                        self.sink.fg(COL_KEYWORD);
                        self.sink.raw_s("}");
                        self.sink.fg("");
                        self.pos += 1;
                    }
                    return Ok(());
                }
            }
            b'}' => {
                // Not valid - but emit as raw
                self.emit1();
                return Ok(());
            }
            b'!' => {
                // negation prefix? But then we need a word boundary. Actually !ls was handled as single command.
                // Treat ! as command when it's a command word.
            }
            _ => {}
        }

        // Try to read the first word
        let _saved = self.pos;
        // First, handle assignments as prefixes
        let mut had_assignment = false;
        loop {
            if let Some((name_len, _)) = self.peek_assignment() {
                // Read `NAME=`
                self.sink.fg(COL_ASSIGN);
                self.sink.raw(&self.src[self.pos..self.pos+name_len].to_vec());
                self.sink.fg("");
                self.pos += name_len;
                self.sink.raw(b"=");
                self.pos += 1;
                // Parse the RHS as a word in assignment context
                self.parse_word(QuoteCtx::Safe, true)?;
                had_assignment = true;
                // Check if followed by whitespace + another word -> more assignment prefixes or command
                self.skip_horiz();
                if self.eof() { return Ok(()); }
                let b = self.src[self.pos];
                if matches!(b, b'\n' | b';' | b'&' | b'|' | b')' | b'}' | b'#') { return Ok(()); }
                // Continue loop to see if next word is also an assignment
                continue;
            }
            break;
        }
        // Redirection?
        if !self.eof() {
            let b = self.src[self.pos];
            if b == b'<' || b == b'>' {
                self.parse_redirection()?;
                self.skip_horiz();
            }
        }
        if self.eof() { return Ok(()); }
        let b = self.src[self.pos];
        if matches!(b, b'\n' | b';' | b'&' | b'|' | b')' | b'}' | b'#') { return Ok(()); }
        // Read command name as a bare word
        let w = self.read_bare_word();
        if w.is_empty() {
            // Parse as a word (maybe starts with quote/dollar)
            self.parse_word(QuoteCtx::Needed, false)?;
            // And then arg list
            self.parse_args()?;
            return Ok(());
        }
        let _ = had_assignment;
        if is_keyword(&w) {
            self.handle_keyword(&w)?;
            return Ok(());
        }
        // Emit command name
        self.sink.fg(COL_COMMAND);
        self.sink.raw(&self.src[self.pos..self.pos+w.len()].to_vec());
        self.sink.fg("");
        self.pos += w.len();
        // Special builtin handling
        match w.as_str() {
            "[" => {
                // Parse until matching ']' on same command - rewriting `-n $x` → `"$x" != ""`
                self.parse_test_args(/*double=*/false)?;
            }
            "test" => {
                self.parse_test_args(/*double=*/false)?;
            }
            "export" | "local" | "declare" | "readonly" => {
                // Already handled as keyword above, but for safety
                self.parse_args()?;
            }
            _ => {
                self.parse_args()?;
            }
        }
        Ok(())
    }

    // After a keyword is recognized, do something with it.
    fn handle_keyword(&mut self, w: &str) -> Result<(), String> {
        // emit keyword
        self.sink.fg(COL_KEYWORD);
        self.sink.raw(&self.src[self.pos..self.pos+w.len()].to_vec());
        self.pos += w.len();
        self.sink.fg("");
        match w {
            "for" | "select" => {
                // Expect: VAR in ... ; do ... done
                self.skip_horiz();
                // read var name (identifier)
                let v = self.read_identifier();
                if !v.is_empty() {
                    self.sink.fg(COL_ASSIGN);
                    self.sink.raw(&self.src[self.pos..self.pos+v.len()].to_vec());
                    self.pos += v.len();
                    self.sink.fg("");
                }
                self.parse_args()?;
            }
            "case" => {
                // case WORD in ... esac
                self.skip_horiz();
                // The head word is safe (no quoting needed)
                self.parse_word(QuoteCtx::Safe, false)?;
                self.parse_args()?;
            }
            "function" => {
                self.skip_horiz();
                let name = self.read_bare_word();
                if !name.is_empty() {
                    self.sink.fg(COL_COMMAND);
                    self.sink.raw(&self.src[self.pos..self.pos+name.len()].to_vec());
                    self.pos += name.len();
                    self.sink.fg("");
                }
                // parse rest (possibly `()` and then body)
                self.parse_args()?;
            }
            "export" | "local" | "declare" | "readonly" => {
                // Each arg may be either NAME or NAME=VAL
                self.parse_declarator_args()?;
            }
            "if" | "while" | "until" | "then" | "else" | "elif" | "do" | "done" | "fi" | "esac" | "in" | "{" | "}" => {
                // just normal keyword
            }
            _ => {}
        }
        Ok(())
    }

    fn parse_declarator_args(&mut self) -> Result<(), String> {
        loop {
            self.skip_horiz();
            if self.eof() { return Ok(()); }
            let b = self.src[self.pos];
            if matches!(b, b'\n' | b';' | b'&' | b'|' | b')' | b'}' | b'#') { return Ok(()); }
            // Read one word
            // If it's `NAME=value`, highlight NAME as assignment
            if let Some((name_len, _)) = self.peek_assignment() {
                self.sink.fg(COL_ASSIGN);
                self.sink.raw(&self.src[self.pos..self.pos+name_len].to_vec());
                self.sink.fg("");
                self.pos += name_len;
                self.sink.raw(b"=");
                self.pos += 1;
                self.parse_word(QuoteCtx::Safe, true)?;
            } else {
                // plain NAME or -option
                let w = self.read_bare_word();
                if w.is_empty() {
                    self.parse_word(QuoteCtx::Needed, false)?;
                } else {
                    self.sink.fg(COL_COMMAND);
                    self.sink.raw(&self.src[self.pos..self.pos+w.len()].to_vec());
                    self.pos += w.len();
                    self.sink.fg("");
                }
            }
        }
    }

    // Redirection: like `>foo`, `>>foo`, `<foo`, `2>&1` etc.
    fn parse_redirection(&mut self) -> Result<(), String> {
        // Emit operator
        let b = self.src[self.pos];
        self.emit1();
        if !self.eof() && self.src[self.pos] == b {
            self.emit1();
        }
        if !self.eof() && self.src[self.pos] == b'&' {
            self.emit1();
        }
        // target
        self.skip_horiz_no_emit();
        // Emit any horizontal whitespace before
        self.parse_word(QuoteCtx::Needed, false)?;
        Ok(())
    }

    fn skip_horiz_no_emit(&mut self) {
        // doesn't skip; just for naming
    }

    // Parse test args up to closing ']' or end of command
    fn parse_test_args(&mut self, _double: bool) -> Result<(), String> {
        // Look for -n $var or -z $var patterns
        loop {
            self.skip_horiz();
            if self.eof() { return Ok(()); }
            let b = self.src[self.pos];
            if matches!(b, b'\n' | b';' | b'&' | b'|' | b')' | b'#') { return Ok(()); }
            // is it `-n` or `-z` followed by whitespace and a variable?
            if b == b'-' && (self.peek(1) == Some(b'n') || self.peek(1) == Some(b'z')) {
                // Check next char is whitespace
                let is_word_end = self.peek(2).map_or(true, |c| matches!(c, b' ' | b'\t'));
                if is_word_end {
                    // Peek ahead: is the argument a single unquoted $var?
                    let mut look = self.pos + 2;
                    while look < self.src.len() && (self.src[look] == b' ' || self.src[look] == b'\t') {
                        look += 1;
                    }
                    // Check that there's an unquoted $var
                    let dollar_start = look;
                    let is_bareword_var = self.try_barevar_from(look).is_some();
                    if is_bareword_var {
                        let is_n = self.src[self.pos+1] == b'n';
                        let replacement = if is_n { " != \"\"" } else { " = \"\"" };
                        // In transform mode, output `"$x" != ""` and skip original `-n $x`
                        // In suggest mode, show `-n ` with red background, then the $var wrapped in quotes (green), and append " != \"\""
                        self.sink.changed = true;
                        let orig_start = self.pos;
                        // Skip `-n ` (or `-z `)
                        if self.sink.mode.transform() {
                            // Don't emit `-n `
                            self.pos = dollar_start;
                            // Emit `"$var"`
                            self.sink.raw(b"\"");
                            self.emit_var_here()?;
                            self.sink.raw(b"\"");
                            self.sink.raw(replacement.as_bytes());
                        } else {
                            // Suggest mode: emit with bg_delete
                            self.sink.bg(BG_DELETE);
                            self.sink.raw(&self.src[orig_start..dollar_start].to_vec());
                            // Then the var with quotes (as insert)
                            self.sink.bg(BG_INSERT);
                            self.sink.raw(b"\"");
                            // restore fg for var color
                            self.pos = dollar_start;
                            self.emit_var_here()?;
                            self.sink.bg(BG_INSERT);
                            self.sink.raw(b"\"");
                            self.sink.raw(replacement.as_bytes());
                            self.sink.bg("");
                            self.sink.fg("");
                        }
                        continue;
                    }
                }
            }
            // Regular test arg
            self.parse_word(QuoteCtx::Needed, false)?;
        }
    }

    // Given position of `$`, detect it's a bare $var followed by whitespace/end.
    fn try_barevar_from(&self, at: usize) -> Option<usize> {
        if at >= self.src.len() || self.src[at] != b'$' { return None; }
        if at + 1 >= self.src.len() { return None; }
        let b = self.src[at+1];
        let mut end;
        if b == b'{' {
            let mut depth = 1;
            end = at + 2;
            while end < self.src.len() && depth > 0 {
                match self.src[end] {
                    b'{' => depth += 1,
                    b'}' => depth -= 1,
                    _ => {}
                }
                end += 1;
            }
        } else if is_id_start(b) {
            end = at + 2;
            while end < self.src.len() && is_id_cont(self.src[end]) { end += 1; }
        } else if matches!(b, b'?' | b'$' | b'!' | b'#' | b'@' | b'*' | b'-' | b'0'..=b'9') {
            end = at + 2;
        } else {
            return None;
        }
        // Next should be whitespace or end of command
        if end < self.src.len() {
            let nb = self.src[end];
            if !matches!(nb, b' ' | b'\t' | b']' | b';' | b'&' | b'|' | b'\n' | b'\r' | b')' | b'#') {
                return None;
            }
        }
        Some(end)
    }

    fn emit_var_here(&mut self) -> Result<(), String> {
        // Parse the $... expression at current pos and emit it colored
        self.parse_dollar(QuoteCtx::Safe)?;
        Ok(())
    }

    // If we're at a position of the form NAME=, return (name_len, value_start).
    fn peek_assignment(&self) -> Option<(usize, usize)> {
        if self.eof() { return None; }
        if !is_id_start(self.src[self.pos]) { return None; }
        let mut i = self.pos + 1;
        while i < self.src.len() && is_id_cont(self.src[i]) { i += 1; }
        // Optionally support NAME[...]=
        if i < self.src.len() && self.src[i] == b'[' {
            // array assignment: NAME[..]=
            let mut j = i + 1;
            let mut depth = 1;
            while j < self.src.len() && depth > 0 {
                match self.src[j] {
                    b'[' => depth += 1,
                    b']' => depth -= 1,
                    _ => {}
                }
                j += 1;
            }
            if j < self.src.len() && self.src[j] == b'=' {
                return Some((j - self.pos, j + 1));
            }
            return None;
        }
        if i < self.src.len() && self.src[i] == b'=' {
            return Some((i - self.pos, i + 1));
        }
        None
    }

    // Read a bare word (no quotes / dollars / specials) and return it.
    // Does not consume.
    fn read_bare_word(&self) -> String {
        let mut i = self.pos;
        let mut s = String::new();
        while i < self.src.len() {
            let b = self.src[i];
            if is_metachar(b) { break; }
            if b == b'\'' || b == b'"' || b == b'`' || b == b'\\' || b == b'$' || b == b'#' {
                break;
            }
            s.push(b as char);
            i += 1;
        }
        s
    }

    fn read_identifier(&self) -> String {
        let mut i = self.pos;
        let mut s = String::new();
        if i >= self.src.len() || !is_id_start(self.src[i]) { return s; }
        s.push(self.src[i] as char);
        i += 1;
        while i < self.src.len() && is_id_cont(self.src[i]) {
            s.push(self.src[i] as char);
            i += 1;
        }
        s
    }

    // Parse the arg list for a command.
    fn parse_args(&mut self) -> Result<(), String> {
        loop {
            self.skip_horiz();
            if self.eof() { return Ok(()); }
            let b = self.src[self.pos];
            if matches!(b, b'\n' | b';' | b'&' | b'|' | b')' | b'}' | b'#') { return Ok(()); }
            // Redirection mid-arglist
            if b == b'<' || b == b'>' {
                self.parse_redirection()?;
                continue;
            }
            self.parse_word(QuoteCtx::Needed, false)?;
        }
    }

    // Parse a word (possibly quoted) up to next unquoted whitespace/metachar.
    // `in_assign_rhs`: affects some heuristics.
    fn parse_word(&mut self, ctx: QuoteCtx, in_assign_rhs: bool) -> Result<(), String> {
        let _ = in_assign_rhs;
        // Detect if we should suggest quoting for the whole word.
        // Simple heuristic: if the word starts with `$` and isn't special and we're in a needs-quoting context,
        // wrap the `$...` portion in quotes.
        //
        // We actually handle piece-by-piece here.
        while !self.eof() {
            let b = self.src[self.pos];
            // Word delimiters
            if matches!(b, b' ' | b'\t' | b'\n' | b'\r' | b';' | b'&' | b'|' | b')' | b'#') {
                return Ok(());
            }
            match b {
                b'"' => {
                    self.parse_dquote_string()?;
                }
                b'\'' => {
                    self.parse_squote_string()?;
                }
                b'$' => {
                    // Is it a case for quoting?
                    if ctx == QuoteCtx::Needed {
                        // Special: $? $$ $! $# don't need quoting
                        if matches!(self.peek(1), Some(b'?') | Some(b'$') | Some(b'!') | Some(b'#')) {
                            self.parse_dollar(ctx)?;
                        } else if self.peek(1) == Some(b'{') && self.is_dollar_brace_special() {
                            // ${#...} etc - invariably numeric
                            self.parse_dollar(ctx)?;
                        } else if self.peek(1).map_or(false, |c| c >= b'0' && c <= b'9') {
                            // Potential $10 pitfall
                            if let Some(err) = self.check_number_pitfall() { return Err(err); }
                            self.suggest_quote_around_dollar(ctx)?;
                        } else {
                            self.suggest_quote_around_dollar(ctx)?;
                        }
                    } else {
                        if self.peek(1).map_or(false, |c| c >= b'0' && c <= b'9') {
                            if let Some(err) = self.check_number_pitfall() { return Err(err); }
                        }
                        self.parse_dollar(ctx)?;
                    }
                }
                b'`' => {
                    self.parse_backtick(ctx)?;
                }
                b'\\' => {
                    self.sink.fg(COL_ESCAPE);
                    self.emit1();
                    if !self.eof() { self.emit1(); }
                    self.sink.fg("");
                }
                b'(' => {
                    // in an assignment RHS: array (...)
                    if in_assign_rhs {
                        self.sink.fg("");
                        self.emit1();
                        // parse inner as words
                        self.parse_array_contents()?;
                        if self.peek(0) == Some(b')') {
                            self.sink.fg("");
                            self.emit1();
                        }
                    } else {
                        self.sink.fg("");
                        self.emit1();
                    }
                }
                _ => {
                    self.sink.fg("");
                    self.emit1();
                }
            }
        }
        Ok(())
    }

    // $10 check: if current pos is '$' followed by digit followed by digit
    fn check_number_pitfall(&self) -> Option<String> {
        if self.peek(0) != Some(b'$') { return None; }
        let b1 = self.peek(1)?;
        let b2 = self.peek(2)?;
        if (b1 >= b'0' && b1 <= b'9') && (b2 >= b'0' && b2 <= b'9') {
            return Some(err_pitfall_10());
        }
        None
    }

    fn is_dollar_brace_special(&self) -> bool {
        // $ at current pos; check if ${#...} 
        if self.peek(2) == Some(b'#') { return true; }
        false
    }

    // Emit a $... piece wrapped in quotes (suggested).
    fn suggest_quote_around_dollar(&mut self, ctx: QuoteCtx) -> Result<(), String> {
        self.sink.changed = true;
        if self.sink.mode.transform() {
            self.sink.raw(b"\"");
            self.parse_dollar(QuoteCtx::Safe)?;
            self.sink.raw(b"\"");
        } else {
            // Suggestion: emit a green-bg `"` before and after, with var color inside
            self.sink.bg(BG_INSERT);
            self.sink.raw(b"\"");
            self.sink.fg("");
            self.parse_dollar(QuoteCtx::Safe)?;
            self.sink.bg(BG_INSERT);
            self.sink.raw(b"\"");
            self.sink.bg("");
            self.sink.fg("");
        }
        let _ = ctx;
        Ok(())
    }

    fn parse_array_contents(&mut self) -> Result<(), String> {
        loop {
            self.skip_blanks_and_newlines();
            if self.eof() { return Err(err_eof()); }
            if self.src[self.pos] == b')' { return Ok(()); }
            self.parse_word(QuoteCtx::Needed, false)?;
        }
    }

    // Parse "..." string
    fn parse_dquote_string(&mut self) -> Result<(), String> {
        self.sink.fg(COL_DQUOTE);
        self.sink.raw(b"\"");
        self.pos += 1;
        while !self.eof() {
            let b = self.src[self.pos];
            match b {
                b'"' => {
                    self.sink.fg(COL_DQUOTE);
                    self.sink.raw(b"\"");
                    self.pos += 1;
                    self.sink.fg("");
                    return Ok(());
                }
                b'\\' => {
                    self.sink.fg(COL_DQUOTE);
                    self.emit1();
                    if !self.eof() {
                        self.emit1();
                    }
                }
                b'$' => {
                    if self.peek(1).map_or(false, |c| c >= b'0' && c <= b'9') {
                        if let Some(err) = self.check_number_pitfall() { return Err(err); }
                    }
                    // ${var} -> $var rewrite if it's a simple identifier inside
                    self.maybe_rewrite_brace_var_in_dquote()?;
                }
                b'`' => {
                    // Inside dquote, backticks should be rewritten to $()
                    self.rewrite_backtick_in_dquote()?;
                }
                _ => {
                    self.sink.fg(COL_DQUOTE);
                    self.emit1();
                }
            }
        }
        Err(err_eof())
    }

    // Attempt to rewrite "${var}" -> "$var" when `{var}` is a simple identifier
    fn maybe_rewrite_brace_var_in_dquote(&mut self) -> Result<(), String> {
        if self.peek(1) == Some(b'{') {
            // Check what's inside
            let start_brace = self.pos + 2;
            let mut i = start_brace;
            if i < self.src.len() && is_id_start(self.src[i]) {
                let mut j = i + 1;
                while j < self.src.len() && is_id_cont(self.src[j]) { j += 1; }
                if j < self.src.len() && self.src[j] == b'}' {
                    // Check: is the following char an identifier-start? If yes, braces are required.
                    let follow = if j + 1 < self.src.len() { Some(self.src[j+1]) } else { None };
                    let needs_braces = match follow {
                        Some(c) if is_id_cont(c) => true,
                        _ => false,
                    };
                    if !needs_braces {
                        // Rewrite to $name
                        self.sink.changed = true;
                        if self.sink.mode.transform() {
                            self.sink.fg(COL_VAR);
                            self.sink.raw(b"$");
                            self.sink.raw(&self.src[i..j].to_vec());
                            self.pos = j + 1;
                            self.sink.fg(COL_DQUOTE);
                        } else {
                            // Suggestion: show removal of the braces
                            self.sink.fg(COL_VAR);
                            self.sink.raw(b"$");
                            self.sink.bg(BG_DELETE);
                            self.sink.raw(b"{");
                            self.sink.fg(COL_VAR);
                            self.sink.raw(&self.src[i..j].to_vec());
                            self.sink.bg(BG_DELETE);
                            self.sink.raw(b"}");
                            self.sink.bg("");
                            self.sink.fg(COL_DQUOTE);
                            self.pos = j + 1;
                        }
                        return Ok(());
                    }
                }
            }
        }
        // Fallback: regular dollar inside dquote
        self.parse_dollar(QuoteCtx::InDQuote)?;
        self.sink.fg(COL_DQUOTE);
        Ok(())
    }

    fn rewrite_backtick_in_dquote(&mut self) -> Result<(), String> {
        // Change `...` -> $(...)
        self.sink.changed = true;
        let start = self.pos;
        // Find matching backtick
        let mut end = self.pos + 1;
        while end < self.src.len() {
            if self.src[end] == b'\\' && end + 1 < self.src.len() { end += 2; continue; }
            if self.src[end] == b'`' { break; }
            end += 1;
        }
        if end >= self.src.len() { return Err(err_eof()); }
        if self.sink.mode.transform() {
            self.sink.raw(b"$(");
            // emit contents with variable highlighting, unescape backslash-quote etc.
            let inner = &self.src[start+1..end].to_vec();
            // Re-parse inner as a command
            let mut inner_parser = Parser::new(inner, OutputMode::Transform);
            let _ = inner_parser.parse_script(EndCond::Eof);
            self.sink.out.extend_from_slice(&inner_parser.sink.out);
            self.sink.raw(b")");
            self.pos = end + 1;
        } else {
            // Suggestion view: original ` shown with bg_delete, insert $(  before, end ` and )
            self.sink.bg(BG_DELETE);
            self.sink.raw(b"`");
            self.sink.bg(BG_INSERT);
            self.sink.raw(b"$(");
            // parse inner with current mode
            let inner_pos = self.pos + 1;
            self.pos = inner_pos;
            // Re-enter parse_script but stopping at backtick
            self.parse_script(EndCond::Backtick)?;
            self.sink.bg(BG_DELETE);
            self.sink.raw(b"`");
            self.sink.bg(BG_INSERT);
            self.sink.raw(b")");
            self.sink.bg("");
            self.sink.fg(COL_DQUOTE);
            self.pos = end + 1;
        }
        Ok(())
    }

    fn parse_squote_string(&mut self) -> Result<(), String> {
        self.sink.fg(COL_SQUOTE);
        self.sink.raw(b"'");
        self.pos += 1;
        while !self.eof() {
            if self.src[self.pos] == b'\'' {
                self.sink.raw(b"'");
                self.pos += 1;
                self.sink.fg("");
                return Ok(());
            }
            self.emit1();
        }
        Err(err_eof())
    }

    fn parse_dollar(&mut self, ctx: QuoteCtx) -> Result<(), String> {
        // Already at '$'
        if self.peek(0) != Some(b'$') { return Ok(()); }
        if self.peek(1) == Some(b'(') {
            if self.peek(2) == Some(b'(') {
                // $((...))
                self.parse_arith()?;
                return Ok(());
            } else {
                // $(...)
                self.parse_subshell(ctx)?;
                return Ok(());
            }
        }
        if self.peek(1) == Some(b'{') {
            // ${...}
            self.parse_brace_var(ctx)?;
            return Ok(());
        }
        // $x or $?
        self.parse_simple_var(ctx)?;
        Ok(())
    }

    fn parse_arith(&mut self) -> Result<(), String> {
        // $((...))
        let start = self.pos;
        self.pos += 3;
        let mut depth = 2;
        while self.pos < self.src.len() && depth > 0 {
            let b = self.src[self.pos];
            if b == b'(' { depth += 1; }
            else if b == b')' { depth -= 1; }
            self.pos += 1;
        }
        self.sink.fg(COL_DBRACKET);
        self.sink.raw(&self.src[start..self.pos].to_vec());
        self.sink.fg("");
        Ok(())
    }

    fn parse_subshell(&mut self, _ctx: QuoteCtx) -> Result<(), String> {
        // $(...)
        // Emit `$(` as plain, then parse inner, then `)`.
        self.sink.fg("");
        self.sink.raw(b"$(");
        self.pos += 2;
        self.parse_script(EndCond::RParen)?;
        if self.peek(0) == Some(b')') {
            self.sink.fg("");
            self.sink.raw(b")");
            self.pos += 1;
        } else {
            return Err(err_eof());
        }
        Ok(())
    }

    fn parse_brace_var(&mut self, _ctx: QuoteCtx) -> Result<(), String> {
        let start = self.pos;
        self.pos += 2;
        let mut depth = 1;
        while self.pos < self.src.len() && depth > 0 {
            match self.src[self.pos] {
                b'{' => depth += 1,
                b'}' => depth -= 1,
                _ => {}
            }
            if depth > 0 { self.pos += 1; }
        }
        if self.pos < self.src.len() { self.pos += 1; }
        self.sink.fg(COL_VAR);
        self.sink.raw(&self.src[start..self.pos].to_vec());
        self.sink.fg("");
        Ok(())
    }

    fn parse_simple_var(&mut self, _ctx: QuoteCtx) -> Result<(), String> {
        let start = self.pos;
        self.pos += 1;
        if self.eof() {
            // just `$`
            self.sink.fg("");
            self.sink.raw(b"$");
            return Ok(());
        }
        let b = self.src[self.pos];
        match b {
            b'?' | b'$' | b'!' | b'#' | b'@' | b'*' | b'-' | b'_' => {
                self.pos += 1;
            }
            b'0'..=b'9' => {
                self.pos += 1;
            }
            c if is_id_start(c) => {
                self.pos += 1;
                while self.pos < self.src.len() && is_id_cont(self.src[self.pos]) {
                    self.pos += 1;
                }
            }
            _ => {
                // lone $
                self.sink.fg("");
                self.sink.raw(b"$");
                return Ok(());
            }
        }
        self.sink.fg(COL_VAR);
        self.sink.raw(&self.src[start..self.pos].to_vec());
        self.sink.fg("");
        Ok(())
    }

    fn parse_backtick(&mut self, _ctx: QuoteCtx) -> Result<(), String> {
        // Preserve as-is (outside dquote). Inside dquote handled separately.
        self.sink.fg("");
        self.emit1(); // `
        // parse contents until matching backtick
        self.parse_script(EndCond::Backtick)?;
        if self.peek(0) == Some(b'`') {
            self.sink.fg("");
            self.emit1();
        } else {
            return Err(err_eof());
        }
        Ok(())
    }
}
