// - flush() emits color only if needed before raw bytes
// - if pending = "" (reset) and we're already at "", no emission
// - if pending = c and we're at c, no emission
// - otherwise emit pending and update current
pub struct Sink {
    pub mode: OutputMode,
    pub out: Vec<u8>,
    pub changed: bool,
    cur: &'static str,
    pending: Option<&'static str>,
}

