        self.flush();
        self.out.extend_from_slice(b);
    }
    pub fn raw_s(&mut self, s: &str) {
        self.raw(s.as_bytes());
    }

    // Explicitly set the SGR sequence for subsequent raw.
    fn set_code(&mut self, code: &'static str) {
        self.pending = Some(code);
    }

    // Set foreground color (only emitted if syntax mode).
    pub fn fg(&mut self, code: &'static str) {
        if self.mode.syntax() {
            self.set_code(code);
        } else {
            // Not syntax mode: fg(<color>) means "reset"
            self.set_code("");
        }
    }

