    pub fn bg(&mut self, code: &'static str) {
        if self.mode.suggest() {
            self.set_code(code);
        }
        // else: no-op
    }

    // Explicit reset request
    pub fn end(&mut self) {
        self.set_code("");
        self.flush();
    }
}
